//! Review item F3 of rust-domain-3: `largest_inner_rectangle` used to test every grid cell against
//! the whole boundary (cells x vertices: 5.5 s for a 60 m floor with 404 vertices in a release
//! build, minutes for larger ones). These tests pin the prepared per-row scan:
//!
//! - the toothed floors of the review and other many-vertex outlines give Python's rectangle and
//!   frame bit for bit (`tests-golden/domain/part4_framing.json`, generated by
//!   `gen_domain4_framing.py`), and each finishes well under a second in a debug build;
//! - a differential on 360 pseudo-random outlines gives the same rectangle (bit for bit) and the
//!   same frame as the pre-F3 implementation, kept as `largest_inner_rectangle_reference`;
//! - outlines beyond the work bounds get no frame, quickly, with a note saying why, and
//!   `generate_candidates` reports that note instead of "No usable rectangular area".

mod common;

use std::time::{Duration, Instant};

use serde_json::Value;
use ss_core::Contract;
use ss_domain::contracts::geometry::{Coord, Fixture, LayoutPreferences, Opening, SiteGeometry};
use ss_domain::design::geometry::framing::{
    frame_for_solver, frame_for_solver_checked, frame_for_solver_reference,
    largest_inner_rectangle, largest_inner_rectangle_checked, largest_inner_rectangle_reference,
    Frame, MAX_FRAME_NEAR_WORK, MAX_FRAME_VERTEX_ROWS, MIN_FRAME_AREA,
};
use ss_domain::design::geometry::solver::generate_candidates;

fn bits(r: Option<(f64, f64, f64, f64)>) -> Option<[u64; 4]> {
    r.map(|(a, b, c, d)| [a.to_bits(), b.to_bits(), c.to_bits(), d.to_bits()])
}

fn site_with(boundary: Vec<Coord>, door: Option<(Coord, Coord)>) -> SiteGeometry {
    let entrances: Vec<Value> = door
        .map(|(a, b)| {
            vec![serde_json::json!({"kind": "entrance", "start": [a.0, a.1], "end": [b.0, b.1]})]
        })
        .unwrap_or_default();
    SiteGeometry::from_json_value(serde_json::json!({
        "property_id": "1afeb98f-0000-4000-8000-0000000000f3",
        "source_id": "synthetic-f3",
        "geometry_source": "FIXTURE",
        "data_origin": "FIXTURE_SYNTHETIC",
        "floor_boundary": boundary.iter().map(|p| vec![p.0, p.1]).collect::<Vec<_>>(),
        "entrances": entrances,
    }))
    .expect("synthetic site")
}

/// The review's `jagged(W, H, n)`: n teeth 0.05 m deep along the bottom wall (4n + 4 vertices).
fn toothed_bottom(w: f64, h: f64, n: usize) -> Vec<Coord> {
    let mut pts = vec![(0.0, 0.0)];
    let step = w / n as f64;
    for i in 0..n {
        let x = i as f64 * step;
        pts.extend([
            (x + step * 0.25, 0.0),
            (x + step * 0.25, -0.05),
            (x + step * 0.75, -0.05),
            (x + step * 0.75, 0.0),
        ]);
    }
    pts.extend([(w, 0.0), (w, h), (0.0, h)]);
    pts
}

#[test]
fn many_vertex_floors_match_python_and_are_fast() {
    let doc = common::golden("domain/part4_framing.json");
    let cases = doc["cases"].as_array().expect("cases");
    assert_eq!(cases.len(), 6);
    let mut timings = Vec::new();
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let site = SiteGeometry::from_json_value(c["site"].clone()).expect("site");
        assert_eq!(
            site.floor_boundary.len() as u64,
            c["vertices"].as_u64().unwrap()
        );
        let theirs: Option<(f64, f64, f64, f64)> =
            serde_json::from_value(c["largest_inner_rectangle"].clone()).unwrap();
        let t = Instant::now();
        let rect = largest_inner_rectangle(&site.floor_boundary, 0.2);
        let frame = frame_for_solver(&site, MIN_FRAME_AREA);
        let elapsed = t.elapsed();
        timings.push((name.to_owned(), elapsed));
        assert_eq!(
            bits(rect),
            bits(theirs),
            "{name}: {rect:?} vs Python {theirs:?}"
        );
        let theirs = c["frame"].as_object().expect("Python frames every case");
        let fr = frame.expect("frame");
        assert_eq!(common::to_value(&fr.notes), theirs["notes"], "{name} notes");
        assert_eq!(
            common::to_value(&fr.site),
            theirs["site"],
            "{name} framed site"
        );
        for probe in theirs["to_site"].as_array().unwrap() {
            let p: Coord = serde_json::from_value(probe["p"].clone()).unwrap();
            let q: Coord = serde_json::from_value(probe["q"].clone()).unwrap();
            assert_eq!(fr.to_site(p), q, "{name}: to_site({p:?})");
        }
    }
    for (name, elapsed) in &timings {
        eprintln!("{name}: largest_inner_rectangle + frame_for_solver in {elapsed:?}");
    }
    // The two floors named by the review, each well under a second even in a debug build (the
    // pre-F3 scan took 5.5 s and 317 s for them in a release build). This test runs the scan
    // twice per floor (rectangle and frame), so the limit applies to the pair.
    for (name, elapsed) in &timings {
        if name == "toothed_bottom_60m_404v" || name == "toothed_bottom_199m_2004v" {
            assert!(
                *elapsed < Duration::from_millis(1000),
                "{name} took {elapsed:?}"
            );
        }
    }
}

#[test]
fn outlines_beyond_the_vertex_row_bound_get_no_frame_and_a_note() {
    // 3,600 teeth: 14,404 vertices x 300 rows = 4.3 million > MAX_FRAME_VERTEX_ROWS.
    let boundary = toothed_bottom(60.0, 60.0, 3600);
    assert!(boundary.len() * 300 > MAX_FRAME_VERTEX_ROWS);
    let site = site_with(boundary, Some(((0.0, 5.0), (0.0, 6.0))));
    let t = Instant::now();
    let err = frame_for_solver_checked(&site, MIN_FRAME_AREA).expect_err("bounded");
    assert!(
        t.elapsed() < Duration::from_millis(500),
        "{:?}",
        t.elapsed()
    );
    assert!(
        err.note.starts_with("Floor outline too detailed to frame: 14404 boundary segments x 300 grid rows exceeds the bound of 4000000"),
        "{}",
        err.note
    );
    assert_eq!(frame_for_solver(&site, MIN_FRAME_AREA), None);
    assert_eq!(largest_inner_rectangle(&site.floor_boundary, 0.2), None);
    let cands = generate_candidates(&site, &[], &LayoutPreferences::default(), 2).unwrap();
    assert_eq!(cands.len(), 1);
    assert_eq!(cands[0].name, "none");
    assert!(!cands[0].report.valid);
    assert_eq!(cands[0].report.issues[0].code, "INFEASIBLE");
    assert_eq!(cands[0].report.issues[0].message, err.note);
}

#[test]
fn densely_packed_vertices_hit_the_near_work_bound() {
    // A 30 m floor whose bottom wall carries 20,000 zigzag points packed into 0.4 m: few rows
    // (vertex-row product 3 million, within its bound), but thousands of segments near a few
    // cells, whose exact tolerance tests would cost about the square of that.
    let mut boundary = vec![(0.0, 0.0), (10.0, 0.0)];
    for k in 0..20_000 {
        let x = 10.0 + 0.4 * k as f64 / 20_000.0;
        boundary.push((x, if k % 2 == 0 { 0.0 } else { -0.01 }));
    }
    boundary.extend([(10.4, 0.0), (30.0, 0.0), (30.0, 30.0), (0.0, 30.0)]);
    assert!(boundary.len() * 150 <= MAX_FRAME_VERTEX_ROWS);
    let t = Instant::now();
    let err = largest_inner_rectangle_checked(&boundary, 0.2).expect_err("bounded");
    assert!(
        t.elapsed() < Duration::from_millis(1000),
        "{:?}",
        t.elapsed()
    );
    assert!(
        err.note
            .contains(&format!("work bound {MAX_FRAME_NEAR_WORK}")),
        "{}",
        err.note
    );
}

#[test]
fn grid_bound_refusal_carries_a_note() {
    let ring = vec![
        (0.0, 0.0),
        (1000.0, 0.0),
        (1000.0, 1000.0),
        (500.0, 1000.0),
        (500.0, 1001.0),
        (0.0, 1001.0),
    ];
    let err = largest_inner_rectangle_checked(&ring, 0.2).expect_err("bounded");
    assert_eq!(
        err.note,
        "Floor too large to frame: a 5000 x 5005 cell grid exceeds the bound of 1000000 cells; no layout was generated."
    );
}

// ---- differential against the pre-F3 implementation -----------------------------------------

/// xorshift64*: deterministic, no dependencies.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn unit(&mut self) -> f64 {
        (self.next() >> 11) as f64 / (1u64 << 53) as f64
    }
    fn range(&mut self, lo: f64, hi: f64) -> f64 {
        lo + (hi - lo) * self.unit()
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
    /// A length that is sometimes an exact multiple of the 0.2 m grid, sometimes just off it
    /// (within or beyond the 1e-6 tolerance), sometimes on a cell centre line (where the scan
    /// takes its row parity), sometimes arbitrary.
    fn grid_len(&mut self, lo: f64, hi: f64) -> f64 {
        let base = (self.range(lo, hi) / 0.2).round() * 0.2;
        match self.below(8) {
            0 => base,
            1 => base + 5e-7,
            2 => base - 5e-7,
            3 => base + 2e-6,
            4 => base - 3e-6,
            5 => base + 0.1,
            6 => base + 0.1 - 4e-7,
            _ => self.range(lo, hi),
        }
    }
}

fn rotate(pts: &[Coord], deg: f64, c: Coord) -> Vec<Coord> {
    let (s, k) = deg.to_radians().sin_cos();
    pts.iter()
        .map(|&(x, y)| {
            let (dx, dy) = (x - c.0, y - c.1);
            (c.0 + dx * k - dy * s, c.1 + dx * s + dy * k)
        })
        .collect()
}

fn outline(rng: &mut Rng, kind: u64) -> Vec<Coord> {
    let w = rng.grid_len(3.0, 14.0);
    let h = rng.grid_len(3.0, 12.0);
    match kind {
        // Rectangle.
        0 => vec![(0.0, 0.0), (w, 0.0), (w, h), (0.0, h)],
        // L shape.
        1 => {
            let a = rng.grid_len(1.0, w - 0.5);
            let b = rng.grid_len(1.0, h - 0.5);
            vec![(0.0, 0.0), (w, 0.0), (w, b), (a, b), (a, h), (0.0, h)]
        }
        // U shape.
        2 => {
            let a = rng.grid_len(0.8, w / 2.0 - 0.2);
            let d = rng.grid_len(0.8, h - 0.6);
            vec![
                (0.0, 0.0),
                (w, 0.0),
                (w, h),
                (w - a, h),
                (w - a, h - d),
                (a, h - d),
                (a, h),
                (0.0, h),
            ]
        }
        // Rotated rectangle or L.
        3 => {
            let ang = match rng.below(4) {
                0 => rng.range(-0.01, 0.01),
                1 => 90.0 + rng.range(-1e-6, 1e-6),
                _ => rng.range(-60.0, 60.0),
            };
            let base = if rng.below(2) == 0 {
                vec![(0.0, 0.0), (w, 0.0), (w, h), (0.0, h)]
            } else {
                vec![
                    (0.0, 0.0),
                    (w, 0.0),
                    (w, h / 2.0),
                    (w / 2.0, h / 2.0),
                    (w / 2.0, h),
                    (0.0, h),
                ]
            };
            rotate(&base, ang, (w / 3.0, h / 4.0))
        }
        // Teeth on a random wall (many vertices, some exactly on grid lines).
        4 => {
            let n = 5 + rng.below(60) as usize;
            let depth = [0.05, 0.2, 1e-7, 3e-6, 0.13][rng.below(5) as usize];
            let mut pts = vec![(0.0, 0.0)];
            let step = w / n as f64;
            for i in 0..n {
                let x = i as f64 * step;
                pts.extend([
                    (x + step * 0.25, 0.0),
                    (x + step * 0.25, -depth),
                    (x + step * 0.75, -depth),
                    (x + step * 0.75, 0.0),
                ]);
            }
            pts.extend([(w, 0.0), (w, h), (0.0, h)]);
            let turns = rng.below(4);
            let mut out = pts;
            for _ in 0..turns {
                out = rotate(&out, 90.0, (0.0, 0.0));
            }
            out
        }
        // Star-shaped polygon with many vertices.
        5 => {
            let n = 8 + rng.below(40);
            let (cx, cy) = (w / 2.0, h / 2.0);
            (0..n)
                .map(|k| {
                    let a = std::f64::consts::TAU * k as f64 / n as f64;
                    let r = rng.range(0.55, 1.0) * w.min(h) / 2.0 + 1.0;
                    (cx + r * a.cos(), cy + r * a.sin())
                })
                .collect()
        }
        // Orthogonal staircase.
        6 => {
            let steps = 2 + rng.below(8) as usize;
            let mut pts = vec![(0.0, 0.0), (w, 0.0)];
            let mut y = 0.0;
            for s in 0..steps {
                let x = w * (1.0 - (s as f64 + 1.0) / (steps as f64 + 1.0));
                y += rng.grid_len(0.4, h / steps as f64 + 0.4);
                let last = *pts.last().unwrap();
                pts.push((last.0, y));
                pts.push((x, y));
            }
            pts.push((0.0, y + 0.6));
            pts
        }
        // Degenerate rings: repeated points, collinear vertices, a spike, a bowtie.
        7 => match rng.below(4) {
            0 => vec![
                (0.0, 0.0),
                (0.0, 0.0),
                (w / 2.0, 0.0),
                (w, 0.0),
                (w, h),
                (w, h),
                (0.0, h),
            ],
            1 => vec![
                (0.0, 0.0),
                (w, 0.0),
                (w, h),
                (w / 2.0, h),
                (w / 2.0, h + 2.0),
                (w / 2.0, h),
                (0.0, h),
            ],
            2 => vec![(0.0, 0.0), (w, h), (w, 0.0), (0.0, h)],
            _ => vec![(0.0, 0.0), (w, 0.0), (w, h), (0.0, h), (0.0, 0.0)],
        },
        // Floor far from the origin (projected-coordinate style).
        _ => {
            let (ox, oy) = (rng.range(1e5, 6e5), rng.range(3.7e6, 3.8e6));
            let base = [
                (0.0, 0.0),
                (w, 0.0),
                (w, h * 0.6),
                (w * 0.4, h * 0.6),
                (w * 0.4, h),
                (0.0, h),
            ];
            base.iter().map(|&(x, y)| (x + ox, y + oy)).collect()
        }
    }
}

fn frames_equal(a: &Option<Frame>, b: &Option<Frame>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(a), Some(b)) => {
            a == b && common::to_value(&a.site) == common::to_value(&b.site) && a.notes == b.notes
        }
        _ => false,
    }
}

#[test]
fn prepared_scan_matches_the_pre_f3_scan_on_360_outlines() {
    let mut rng = Rng(0x00F3_1AFE_B98F);
    let mut framed = 0;
    let mut kinds = [0usize; 9];
    // SS_F3_DIFF_CASES widens the run (and SS_F3_DIFF_SEED reseeds it), for example in a
    // release build: `cargo test --release -p ss-domain --test framing_work prepared_scan`.
    let n: u64 = std::env::var("SS_F3_DIFF_CASES")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(360);
    if let Some(seed) = std::env::var("SS_F3_DIFF_SEED")
        .ok()
        .and_then(|v| v.parse().ok())
    {
        rng = Rng(seed);
    }
    for case in 0..n {
        let kind = case % 9;
        kinds[kind as usize] += 1;
        let boundary = outline(&mut rng, kind);
        let rect = largest_inner_rectangle(&boundary, 0.2);
        let reference = largest_inner_rectangle_reference(&boundary, 0.2);
        assert_eq!(
            bits(rect),
            bits(reference),
            "case {case} (kind {kind}): {rect:?} vs reference {reference:?} for {boundary:?}"
        );
        // A frame needs a valid site: skip outlines the contract rejects (bowties, spikes).
        let b = boundary.clone();
        let door = match rng.below(5) {
            0 => None,
            1 => Some((b[0], (b[0].0 + 1.0, b[0].1))),
            _ => {
                let i = rng.below(b.len() as u64) as usize;
                let (p, q) = (b[i], b[(i + 1) % b.len()]);
                Some((p, ((p.0 + q.0) / 2.0, (p.1 + q.1) / 2.0)))
            }
        };
        let entrances: Vec<Value> = door
            .map(|(a, c)| {
                vec![
                    serde_json::json!({"kind": "entrance", "start": [a.0, a.1], "end": [c.0, c.1]}),
                ]
            })
            .unwrap_or_default();
        let sink = b[rng.below(b.len() as u64) as usize];
        let site = SiteGeometry::from_json_value(serde_json::json!({
            "property_id": "1afeb98f-0000-4000-8000-0000000000f3",
            "source_id": "synthetic-f3",
            "geometry_source": "FIXTURE",
            "data_origin": "FIXTURE_SYNTHETIC",
            "floor_boundary": b.iter().map(|p| vec![p.0, p.1]).collect::<Vec<_>>(),
            "entrances": entrances,
            "fixed_walls": [[[b[0].0 + 1.0, b[0].1 + 1.0], [b[0].0 + 2.0, b[0].1 + 1.0]]],
            "fixed_obstacles": [[[sink.0, sink.1], [sink.0 + 0.5, sink.1], [sink.0 + 0.5, sink.1 + 0.5], [sink.0, sink.1 + 0.5]]],
        }));
        let Ok(mut site) = site else { continue };
        site.fixture_locations = vec![Fixture {
            kind: "sink".into(),
            location: (sink.0 + 0.3, sink.1 + 0.3),
            evidence_ids: vec![],
        }];
        let ours = frame_for_solver(&site, MIN_FRAME_AREA);
        let theirs = frame_for_solver_reference(&site, MIN_FRAME_AREA);
        assert!(
            frames_equal(&ours, &theirs),
            "case {case} (kind {kind}): frames differ\n{ours:?}\n{theirs:?}"
        );
        assert!(frame_for_solver_checked(&site, MIN_FRAME_AREA).is_ok());
        if ours.is_some() {
            framed += 1;
        }
    }
    eprintln!("differential: {n} outlines {kinds:?}, {framed} frames compared");
    assert!(framed * 9 >= n as usize * 5, "{framed}");
}

#[test]
fn opening_contract_is_unchanged() {
    // The frame's entrance is still the measured one clamped to the layout wall.
    let site = site_with(
        vec![
            (0.0, 0.0),
            (12.0, 0.0),
            (12.0, 7.0),
            (8.0, 7.0),
            (8.0, 10.0),
            (0.0, 10.0),
        ],
        Some(((5.0, 0.0), (6.2, 0.0))),
    );
    let fr = frame_for_solver(&site, MIN_FRAME_AREA).expect("frame");
    assert_eq!(
        fr.site.entrances,
        vec![Opening {
            kind: "entrance".into(),
            start: (5.0, 0.0),
            end: (6.2, 0.0)
        }]
    );
}

#[test]
fn vertices_on_row_centre_lines_match_the_pre_f3_scan() {
    // Cells away from the boundary are decided by the ray-crossing parity at their row's centre
    // line, so a vertex exactly on that line exercises GEOS's half-open straddle rule. Notches
    // whose corners sit on centre lines (computed as the scan computes them), in four turns.
    let cy = |miny: f64, j: usize| (miny + j as f64 * 0.2 + (miny + (j + 1) as f64 * 0.2)) / 2.0;
    let mut checked = 0;
    for j in [3usize, 20, 21, 34] {
        for (miny, w) in [(0.0, 10.0), (-0.05, 9.3), (2.7, 12.1)] {
            let y = cy(miny, j);
            let top = miny + 10.0;
            let shapes = [
                // Notch at the top right, its lower corners on the centre line of row j.
                vec![
                    (0.0, miny),
                    (w, miny),
                    (w, y),
                    (w - 2.0, y),
                    (w - 2.0, top),
                    (0.0, top),
                ],
                // A step: the right wall ends on the centre line.
                vec![
                    (0.0, miny),
                    (w, miny),
                    (w, y),
                    (w + 1.5, y),
                    (w + 1.5, top),
                    (0.0, top),
                ],
                // A slot cut into the right wall between two centre lines.
                vec![
                    (0.0, miny),
                    (w, miny),
                    (w, y),
                    (w - 3.0, y),
                    (w - 3.0, cy(miny, j + 4)),
                    (w, cy(miny, j + 4)),
                    (w, top),
                    (0.0, top),
                ],
            ];
            for shape in shapes {
                for turns in 0..4 {
                    let mut pts = shape.clone();
                    for _ in 0..turns {
                        pts = rotate(&pts, 90.0, (0.0, 0.0));
                    }
                    for p in [&pts, &shape] {
                        assert_eq!(
                            bits(largest_inner_rectangle(p, 0.2)),
                            bits(largest_inner_rectangle_reference(p, 0.2)),
                            "{p:?}"
                        );
                        checked += 1;
                    }
                }
            }
        }
    }
    assert_eq!(checked, 288);
}
